html.script:
import { setComboboxLoading, setComboboxOptions } from "@zuccadev-labs/zuix-zui/dom";

const repo = document.querySelector("#repo");
repo.addEventListener("z:input", async (event) => {
  setComboboxLoading(repo, true);
  const found = await searchRepositories(event.detail.value);
  setComboboxOptions(repo, found.map((item) => ({ value: item.id, label: item.name, icon: "folder" })));
  setComboboxLoading(repo, false);
});
